INSERT INTO BUDGET(FISCAL_YEAR_ID,TYPE,NAME,AMOUNT,SORT_ORDER) SELECT Y.ID,'INCOME','주정헌금',0,COALESCE((SELECT MAX(B.SORT_ORDER)+1 FROM BUDGET B WHERE B.FISCAL_YEAR_ID=Y.ID AND B.TYPE='INCOME'),0) FROM FISCAL_YEAR Y WHERE Y.CLOSED=FALSE AND NOT EXISTS(SELECT 1 FROM BUDGET B WHERE B.FISCAL_YEAR_ID=Y.ID AND B.TYPE='INCOME' AND B.NAME='주정헌금');
